      -o "$build/lib/NLS/$module.olean" \
      "$repo/NLS/$module.lean" > "$build/logs/$log_name.log" 2>&1; then
    cat -- "$build/logs/$log_name.log"
    exit 1
  fi
  echo "Checked $module"
done
